// fetchRecorder is the httptest stub upstream: it records every request's
// headers and raw query and answers a numbered JSON body.
type fetchRecorder struct {
	mu     sync.Mutex
	hits   int
	fields []http.Header
	querys []string
}

func (r *fetchRecorder) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	r.mu.Lock()
	r.hits++
	n := r.hits
	r.fields = append(r.fields, req.Header.Clone())
	r.querys = append(r.querys, req.URL.RawQuery)
	r.mu.Unlock()
	w.Header().Set("X-Trace", "t-1")
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write([]byte(fmt.Sprintf(`{"id":1,"n":%d}`, n)))
}

func (r *fetchRecorder) count() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.hits
}

func (r *fetchRecorder) header(i int) http.Header {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.fields[i]
}

func (r *fetchRecorder) query(i int) string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.querys[i]
}

func stringVar(v string) *metadatav1.VariableValue {
	return &metadatav1.VariableValue{Kind: &metadatav1.VariableValue_StringValue{StringValue: v}}
}

// TestFetchSource is enrichment box 2.2: the core-side fetch at the
// BuildRequest->Convert stub — populate (substitution + Convert inputs),
// pacing (per-plugin interval, independent across plugins), redacted_ref
// (explicit failure, NO network), and timeout — over httptest stub upstreams.
func TestFetchSource(t *testing.T) {
	ctx := context.Background()

	t.Run("populate: substitution, headers, and ConvertRequest inputs", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()

		spec := &metadatav1.RequestSpec{
			Method:      "GET",
			UrlTemplate: srv.URL + "/api/animes?search={title}&limit={limit}",
			Headers:     map[string]string{"User-Agent": "mellifera/test"},
			Variables: map[string]*metadatav1.VariableValue{
				"title": stringVar("Cowboy Bebop & Spike"),
				"limit": {Kind: &metadatav1.VariableValue_IntValue{IntValue: 10}},
			},
		}
		body, status, headers, err := fetchSource(ctx, nil, "shikimori", spec)
		if err != nil {
			t.Fatalf("fetchSource: %v", err)
		}
		if status != http.StatusOK {
			t.Fatalf("http_status = %d, want 200", status)
		}
		if want := `{"id":1,"n":1}`; string(body) != want {
			t.Fatalf("raw_response = %q, want %q", body, want)
		}
		if headers["X-Trace"] != "t-1" {
			t.Fatalf("response_headers[X-Trace] = %v, want t-1", headers)
		}
		// The value's & arrived percent-encoded, never as a raw separator.
		if got := rec.query(0); !strings.Contains(got, "%26") {
			t.Fatalf("RawQuery = %q, want the search value's & percent-encoded as %%26", got)
		}
		if got := rec.header(0).Get("User-Agent"); got != "mellifera/test" {
			t.Fatalf("upstream User-Agent = %q, want mellifera/test", got)
		}

		// End-to-end at the stub site: runSource feeds the fetched body,
		// status, and headers into ConvertRequest.
		convSeen := make(chan *metadatav1.ConvertRequest, 1)
		src := &captureSource{onConvert: func(cr *metadatav1.ConvertRequest) { convSeen <- cr }, spec: spec}
		resolve := func(string, string) (sdk.MetadataSource, error) { return src, nil }
		mod := module.Module{ID: "serial", MediaType: "serial", MetadataSources: []module.MetadataSourceBinding{binding("shikimori", 1, true)}}
		if _, _, _, err := enrichDoc(ctx, resolve, mod, map[string]any{}, &scannerv1.IdentifyResult{}, nil); err != nil {
			t.Fatalf("enrichDoc: %v", err)
		}
		cr := <-convSeen
		if string(cr.GetRawResponse()) != `{"id":1,"n":2}` {
			t.Fatalf("ConvertRequest.raw_response = %q, want the fetched body", cr.GetRawResponse())
		}
		if cr.GetHttpStatus() != http.StatusOK {
			t.Fatalf("ConvertRequest.http_status = %d, want 200", cr.GetHttpStatus())
		}
		if cr.GetResponseHeaders()["X-Trace"] != "t-1" {
			t.Fatalf("ConvertRequest.response_headers = %v, want X-Trace", cr.GetResponseHeaders())
		}
	})

	t.Run("pacing: per-plugin interval, independent across plugins", func(t *testing.T) {
		at := testTime
		gate := newFetchGate(func() time.Time { return at })

		if d := gate.reserve("shikimori", 700*time.Millisecond); d != 0 {
			t.Fatalf("first send waited %v, want 0", d)
		}
		at = at.Add(40 * time.Millisecond)
		if d := gate.reserve("shikimori", 700*time.Millisecond); d != 660*time.Millisecond {
			t.Fatalf("second send waited %v, want 660ms", d)
		}
		if d := gate.reserve("tmdb", 700*time.Millisecond); d != 0 {
			t.Fatalf("other plugin waited %v, want 0 (independent per plugin)", d)
		}
		at = at.Add(660 * time.Millisecond) // now == send 2's reserved slot
		// Send 3 arriving exactly at send 2's slot books the NEXT slot: with
		// slot reservation, concurrent workers never burst together.
		if d := gate.reserve("shikimori", 700*time.Millisecond); d != 700*time.Millisecond {
			t.Fatalf("third send waited %v, want 700ms (next reserved slot)", d)
		}
		at = at.Add(1400 * time.Millisecond) // past send 3's booked slot (+1400ms)
		if d := gate.reserve("shikimori", 700*time.Millisecond); d != 0 {
			t.Fatalf("slot reached, waited %v, want 0", d)
		}
		// A nil gate is unpaced (sync path, tests).
		if d := (*FetchGate)(nil).reserve("shikimori", 700*time.Millisecond); d != 0 {
			t.Fatalf("nil gate waited %v, want 0", d)
		}

		// Wired end-to-end: consecutive fetches for one plugin through a real
		// gate are spaced at least min_interval_ms apart at the upstream.
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		realGate := NewFetchGate()
		spec := &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL, MinIntervalMs: 150}
		start := time.Now()
		if _, _, _, err := fetchSource(ctx, realGate, "shikimori", spec); err != nil {
			t.Fatalf("first fetch: %v", err)
		}
		first := time.Since(start)
		if _, _, _, err := fetchSource(ctx, realGate, "shikimori", spec); err != nil {
			t.Fatalf("second fetch: %v", err)
		}
		if elapsed := time.Since(start); elapsed < first+130*time.Millisecond {
			t.Fatalf("second fetch returned after %v total; want the 150ms interval enforced (>= first+130ms)", elapsed)
		}
	})

	t.Run("redacted_ref: explicit failure, no network attempt", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		spec := &metadatav1.RequestSpec{
			Method:      "GET",
			UrlTemplate: srv.URL + "?token={api_key}",
			Variables: map[string]*metadatav1.VariableValue{
				"api_key": {Kind: &metadatav1.VariableValue_RedactedRef{RedactedRef: "client:api_key"}},
			},
		}
		_, _, _, err := fetchSource(ctx, nil, "p", spec)
		if !errors.Is(err, errRedactedRef) {
			t.Fatalf("err = %v, want the explicit redacted_ref unsupported error", err)
		}
		if n := rec.count(); n != 0 {
			t.Fatalf("upstream saw %d requests, want 0 (no network attempt)", n)
		}
	})

	t.Run("timeout: timeout_seconds bounds the send", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			time.Sleep(2 * time.Second)
			_, _ = w.Write([]byte(`{}`))
		}))
		defer srv.Close()
		spec := &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL, TimeoutSeconds: 1}
		start := time.Now()
		_, _, _, err := fetchSource(ctx, nil, "p", spec)
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("err = %v, want context.DeadlineExceeded", err)
		}
		if elapsed := time.Since(start); elapsed > 1900*time.Millisecond {
			t.Fatalf("fetch took %v; the 1s timeout_seconds must bound it", elapsed)
		}
	})

	t.Run("validation: method whitelist and unresolvable placeholders", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		if _, _, _, err := fetchSource(ctx, nil, "p", &metadatav1.RequestSpec{Method: "PUT", UrlTemplate: srv.URL}); err == nil {
			t.Fatal("PUT must be rejected (GET/POST only)")
		}
		if _, _, _, err := fetchSource(ctx, nil, "p", &metadatav1.RequestSpec{
			Method:      "GET",
			UrlTemplate: srv.URL + "?q={missing}",
		}); err == nil {
			t.Fatal("unresolvable {missing} placeholder must be rejected")
		}
		if n := rec.count(); n != 0 {
			t.Fatalf("upstream saw %d requests, want 0 (spec validation precedes network)", n)
		}
	})
}

